const fs=require("fs");const path=require("path");const STATE_FILE=path.join(process.cwd(),".claude","learning","agent-state.json");const LOCK_FILE=path.join(process.cwd(),".claude","learning",".state.lock");const LOCK_TIMEOUT_MS=5e3;const STALE_THRESHOLD_MS=10*60*1e3;function acquireLock(){const deadline=Date.now()+LOCK_TIMEOUT_MS;while(Date.now()<deadline){try{fs.writeFileSync(LOCK_FILE,String(process.pid),{flag:"wx"});return true}catch(e){if(e.code==="EEXIST"){try{const stat=fs.statSync(LOCK_FILE);if(Date.now()-stat.mtimeMs>LOCK_TIMEOUT_MS){fs.unlinkSync(LOCK_FILE);continue}}catch(_){}const waitUntil=Date.now()+10;while(Date.now()<waitUntil){}continue}return false}}return false}function releaseLock(){try{fs.unlinkSync(LOCK_FILE)}catch(_){}}function readState(){try{if(!fs.existsSync(STATE_FILE))return{};return JSON.parse(fs.readFileSync(STATE_FILE,"utf8"))}catch(_){return{}}}function writeState(state){const dir=path.dirname(STATE_FILE);if(!fs.existsSync(dir)){fs.mkdirSync(dir,{recursive:true})}fs.writeFileSync(STATE_FILE,JSON.stringify(state,null,2))}function getAgentState(agentId){const states=readState();return states[agentId]||{status:"idle",lastRun:null,metadata:{}}}function setAgentState(agentId,status,metadata={}){if(!acquireLock()){process.stderr.write(`[AgentState] Failed to acquire lock for ${agentId}\n`);return false}try{const states=readState();states[agentId]={status:status,lastRun:(new Date).toISOString(),...metadata};writeState(states);return true}finally{releaseLock()}}function getSummary(){const states=readState();const now=Date.now();const summary={running:[],idle:[],completed:[],failed:[],stale:[]};for(const[agentId,state]of Object.entries(states)){if(state.status==="running"&&state.lastRun&&now-new Date(state.lastRun).getTime()>STALE_THRESHOLD_MS){summary.stale.push(agentId)}else if(summary[state.status]){summary[state.status].push(agentId)}}return summary}function cleanupStale(){if(!acquireLock())return 0;try{const states=readState();const now=Date.now();let cleaned=0;for(const[agentId,state]of Object.entries(states)){if(state.status==="running"&&state.lastRun&&now-new Date(state.lastRun).getTime()>STALE_THRESHOLD_MS){states[agentId]={...state,status:"failed",lastRun:(new Date).toISOString(),failReason:"stale_timeout"};cleaned++}}if(cleaned>0)writeState(states);return cleaned}finally{releaseLock()}}if(require.main===module){const[,,command,agentId,status,...rest]=process.argv;switch(command){case"get":console.log(JSON.stringify(getAgentState(agentId||"unknown"),null,2));break;case"set":if(!agentId||!status){console.error("Usage: agentStateManager.js set <agentId> <status>");process.exit(1)}setAgentState(agentId,status,rest.length>0?JSON.parse(rest[0]):{});console.log(`[AgentState] ${agentId} → ${status}`);break;case"summary":console.log(JSON.stringify(getSummary(),null,2));break;case"cleanup":const cleaned=cleanupStale();console.log(`[AgentState] Cleaned ${cleaned} stale agent(s)`);break;default:console.error("Usage: agentStateManager.js <get|set|summary|cleanup> [agentId] [status]");process.exit(1)}}module.exports={getAgentState:getAgentState,setAgentState:setAgentState,getSummary:getSummary,cleanupStale:cleanupStale};